export function AppLogo({ id, size = 48 }: { id: string; size?: number }) {
  const mark = MARKS[id];
  if (!mark) return null;
  return (
    <svg className="provider-logo" width={size} height={size} viewBox="0 0 24 24" aria-hidden="true" focusable="false">
      <path fill={mark.color ?? "currentColor"} d={mark.d} />
    </svg>
  );
}
